local KTool = CS.Engine.Lib.KTool
local FontStyleButton = CS.Game.Native.Common.FontStyleButton
local UIModule = CS.Engine.UI.UIModule
--- from:  > name: ItemSubmission
---@class OverseaManageTalkingSubGoodsNode
---@field Env                           	OverseaManageTalkingSubGoodsNode        
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field GoodNode                      	Engine.Modules.LuaBehaviour             
---@field BtnAddProp                    	UnityEngine.RectTransform               
---@field FontStyleButton               	UnityEngine.RectTransform               
local OverseaManageTalkingSubGoodsNode = Class('OverseaManageTalkingSubGoodsNode')
local SubType = {
    Assign = 1,
    Random = 2,
}

function OverseaManageTalkingSubGoodsNode:__init()
    self.subData = {}
    self.callBack = nil
end

function OverseaManageTalkingSubGoodsNode:__delete()
    self.subData = nil
    self.callBack = nil
end

function OverseaManageTalkingSubGoodsNode:SetSubCallBack(callBack)
    self.callBack = callBack
end

function OverseaManageTalkingSubGoodsNode:Awake()
    self:InitNodeEnv()
    self:AddUIClick()

end

function OverseaManageTalkingSubGoodsNode:AddUIClick()
    SetButtonAction(self.FontStyleButton.gameObject,Bind(self,self.OnSubBtnClick))
    SetButtonAction(self.BtnAddProp.gameObject,Bind(self,self.OnAddPropBtnClick))
end

function OverseaManageTalkingSubGoodsNode:InitNodeEnv()
    if self.GoodNode then
        local env = CfUtils.GetLuaScr(self.GoodNode,"Game.Behaviours.GoodNodeMB")
        if not isNull(env) then
            self.goodNodeEnv = env
        end
    end
end

function OverseaManageTalkingSubGoodsNode:RefreshAssignGoods(goodsId,num)
    self.subType = SubType.Assign
    self:RefreshCommonGoodsShow(goodsId,num)
end

function OverseaManageTalkingSubGoodsNode:RefreshCommonGoodsShow(goodsId,num)
    self.subData.goodsId = goodsId
    self.subData.num = num
    KTool.SetActive(self.GoodNode.gameObject,true)
    KTool.SetActive(self.BtnAddProp.gameObject,false)
    self:RefreshGoods(goodsId,num)
    self:RefreshSubBtn()
end

function OverseaManageTalkingSubGoodsNode:RefreshRandomGoods(ids,num)
    self.subType = SubType.Random
    self.subData = {}
    self.subData.num = num
    self.ids = ids
    self.FontStyleButton.transform:GetComponent(typeof(FontStyleButton)):ResetFontStyle("B18")
end

function OverseaManageTalkingSubGoodsNode:RefreshSubBtn()
    local isEnough = self.subData.isEnough
    local type = isEnough and "B6" or "B18"
    self.FontStyleButton.transform:GetComponent(typeof(FontStyleButton)):ResetFontStyle(type)
end

function OverseaManageTalkingSubGoodsNode:RefreshGoods(goodsId,num)
    self.goodNodeEnv:Reload({goodsId = goodsId, isShowNo = true,text = self:GetTextShow(num)})
    self.goodNodeEnv:SetClickButtonAction(function(goodsId, id)
        if self.subType == SubType.Assign then
            ----点击出tip
            local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
            if isTable(vo) then
                --GameUtils.ShowCommonTipsBoard(self.GoodNode, vo.name, vo.desc, vo.quality, vo.id)
                GameUtils.ShowCommonGoodsTipsBoard(self.GoodNode.gameObject, vo.id, true)
            end
        else
            self:OnAddPropBtnClick()
        end
    end)
end

function OverseaManageTalkingSubGoodsNode:OnSubBtnClick()
    if isSet(self.subData,"isEnough") then
        if self.subData.isEnough then
            if not isNull(self.callBack) then
                self.callBack(self.subData)
            end
        else
            GameUtils.Toast(localize("道具不足"))
        end
    end
end

function OverseaManageTalkingSubGoodsNode:OnAddPropBtnClick()
    UIModule.OpenDialog({ id = Constants.UITypeIds.MaidCoffeeGuestSubGoodsDialog, parameters = { ids = self.ids, needNum = checkNumber(self.subData.num) } })
end

function OverseaManageTalkingSubGoodsNode:RefreshSubGoodShow(goodsData)
    if not isNull(goodsData) then
        if isNull(self.subData) then
            self.subData = {}
        end
        self.subData.num = 1  ---随机物品只能提交一个
        self.subData.groupId = goodsData.groupId
        self:RefreshCommonGoodsShow(goodsData.goodsId,self.subData.num)
    end
end

function OverseaManageTalkingSubGoodsNode:GetTextShow(num)
    local haveNum = GoodsUtils.GetThingNo(self.subData.goodsId)
    local isEnough = haveNum >= num
    self.subData.isEnough = isEnough
    local color = isEnough and "<color=#FFFFFF>%s</color>" or "<color=#e71f55>%s</color>"
    return string.format("%s/%s",string.format(color,haveNum),num)
end

function OverseaManageTalkingSubGoodsNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return OverseaManageTalkingSubGoodsNode